public class RegonValidator {
    public static boolean validate(String regon) {
        if (regon == null || !regon.matches("\\d{9}")) {
            return false;
        }
        int[] weights = {8, 9, 2, 3, 4, 5, 6, 7};
        int sum = 0;
        for (int i = 0; i < 8; i++) {
            sum += Character.getNumericValue(regon.charAt(i)) * weights[i];
        }
        int remainder = sum % 11;
        int checksum = remainder == 10 ? 0 : remainder;
        return checksum == Character.getNumericValue(regon.charAt(8));
    }
}

