package main

import (
	"regexp"
	"strconv"
)

func ValidateREGON(regon string) bool {
	if matched, _ := regexp.MatchString(`^\d{9}$`, regon); !matched {
		return false
	}
	weights := []int{8, 9, 2, 3, 4, 5, 6, 7}
	sum := 0
	for i := 0; i < 8; i++ {
		digit, _ := strconv.Atoi(string(regon[i]))
		sum += digit * weights[i]
	}
	remainder := sum % 11
	checksum := remainder
	if remainder == 10 {
		checksum = 0
	}
	lastDigit, _ := strconv.Atoi(string(regon[8]))
	return checksum == lastDigit
}

