pub fn validate_regon(regon: &str) -> bool {
    if regon.len() != 9 || !regon.chars().all(|c| c.is_ascii_digit()) {
        return false;
    }
    let weights = [8, 9, 2, 3, 4, 5, 6, 7];
    let digits: Vec<u32> = regon.chars().map(|c| c.to_digit(10).unwrap()).collect();
    let sum: u32 = digits.iter().take(8).zip(weights.iter()).map(|(&d, &w)| d * w).sum();
    let remainder = sum % 11;
    let checksum = if remainder == 10 { 0 } else { remainder };
    checksum == digits[8]
}
